import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 집계 단위를 보내지 않으면 일별로 집계한다.
const DEFAULT_UNIT = '일별';
// 가정: 승인해제 전표는 장부에서 제외하고 승인·마감 전표만 집계한다.
// 가정: balance는 거래처·계정과목별 차변(+)·대변(-) 누적 합이다. 조회 시작일 이전 내역도 포함한다.
// 가정: periodTotal은 거래처·계정과목별로 일·월 단위 차변(+)·대변(-) 합이다.

const DATE_PATTERN = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;

const LEDGER_SQL = `
WITH ledger AS (
  SELECT
    p.partner_name,
    a.account_name,
    jv.voucher_date,
    vl.dc_type,
    vl.amount,
    vl.partner_id,
    vl.account_item_id,
    jv.journal_voucher_id,
    vl.line_no,
    CASE WHEN vl.dc_type = 'DEBIT' THEN vl.amount ELSE -vl.amount END AS signed_amount,
    SUM(CASE WHEN vl.dc_type = 'DEBIT' THEN vl.amount ELSE -vl.amount END)
      OVER (PARTITION BY vl.partner_id, vl.account_item_id
            ORDER BY jv.voucher_date, jv.journal_voucher_id, vl.line_no) AS balance
  FROM voucher_line vl
  JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id
  JOIN partner p ON p.partner_id = vl.partner_id
  JOIN account_item a ON a.account_item_id = vl.account_item_id
  WHERE jv.voucher_date <= CAST(:dateTo AS date)
    AND jv.status IN ('승인', '마감')
    AND (CAST(:partnerId AS bigint) IS NULL OR vl.partner_id = CAST(:partnerId AS bigint))
    AND (CAST(:accountItemId AS bigint) IS NULL OR vl.account_item_id = CAST(:accountItemId AS bigint))
),
ranged AS (
  SELECT
    l.*,
    SUM(l.signed_amount) OVER (
      PARTITION BY l.partner_id, l.account_item_id,
        CASE WHEN CAST(:unit AS text) = '월별'
          THEN date_trunc('month', l.voucher_date)
          ELSE date_trunc('day', l.voucher_date)
        END
    ) AS period_total
  FROM ledger l
  WHERE l.voucher_date >= CAST(:dateFrom AS date)
)
`;

function textOf(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }
  const trimmed = value.trim();
  return trimmed === '' ? null : trimmed;
}

function idOf(value: unknown): string | null {
  const text = textOf(value);
  if (text === null) {
    return null;
  }
  if (!/^\d{1,18}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '거래처·계정과목 값이 올바르지 않습니다.');
  }
  return text;
}

function wholeOf(value: unknown, fallback: number, name: string): number {
  const text = textOf(value);
  if (text === null) {
    return fallback;
  }
  if (!/^\d{1,9}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 올바르지 않습니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr00806Controller {
  @Get('/partner-ledgers')
  async listPartnerLedgers(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '임직원');
    const query = checks.queryOf(req.query);
    const dateFrom = textOf(query['dateFrom']);
    const dateTo = textOf(query['dateTo']);
    if (dateFrom === null || dateTo === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일과 종료일을 입력해 주세요.');
    }
    if (!DATE_PATTERN.test(dateFrom) || !DATE_PATTERN.test(dateTo) || dateFrom > dateTo) {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 기간이 올바르지 않습니다.');
    }
    const unit = textOf(query['aggregationUnit']) ?? DEFAULT_UNIT;
    if (unit !== '일별' && unit !== '월별') {
      throw new ApiError(422, 'INVALID_AGGREGATION_UNIT', '집계 단위는 일별 또는 월별만 선택할 수 있습니다.');
    }
    const partnerId = idOf(query['partnerId']);
    const accountItemId = idOf(query['accountItemId']);
    const page = wholeOf(query['page'], 0, '쪽 번호');
    const size = Math.min(wholeOf(query['size'], DEFAULT_SIZE, '쪽 크기'), MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기는 1 이상이어야 합니다.');
    }
    const filterParams = {
      dateFrom,
      dateTo,
      unit,
      partnerId,
      accountItemId,
    };
    return transaction(async (db) => {
      const countRows = await db.query(
        LEDGER_SQL + 'SELECT COUNT(*) AS "total" FROM ranged',
        filterParams,
      );
      const items = await db.query(
        LEDGER_SQL +
          `SELECT
  r.partner_name AS "partnerName",
  r.account_name AS "accountName",
  r.voucher_date AS "voucherDate",
  r.dc_type AS "dcType",
  r.amount AS "amount",
  r.balance AS "balance",
  r.period_total AS "periodTotal"
FROM ranged r
ORDER BY r.partner_name, r.account_name, r.voucher_date, r.journal_voucher_id, r.line_no
LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...filterParams, size, offset: page * size },
      );
      return {
        items,
        page,
        size,
        total: Number(countRows[0]?.['total'] ?? 0),
      };
    });
  }
}

