import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Tiles,
  Field,
  DateInput,
  Select,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const PAGE_SIZE = 20;

interface Applied {
  dateFrom: string;
  dateTo: string;
  partnerId: unknown;
  accountItemId: unknown;
  aggregationUnit: string;
}

const EMPTY_PAGE: Page = { items: [], page: 0, size: PAGE_SIZE, total: 0 };

export default function FnSfr00806Page({ role, notify }: PageProps) {
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [aggregationUnit, setAggregationUnit] = useState('일별');
  const [applied, setApplied] = useState<Applied | null>(null);
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (applied === null) {
      return EMPTY_PAGE;
    }
    return call<Page>('GET', '/partner-ledgers', role, undefined, {
      dateFrom: applied.dateFrom,
      dateTo: applied.dateTo,
      partnerId: applied.partnerId,
      accountItemId: applied.accountItemId,
      aggregationUnit: applied.aggregationUnit,
      page,
      size: PAGE_SIZE,
    });
  }, [applied, page, role]);

  const search = () => {
    if (dateFrom === '' || dateTo === '') {
      setFormError('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (dateFrom > dateTo) {
      setFormError('조회 기간이 올바르지 않습니다.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ dateFrom, dateTo, partnerId, accountItemId, aggregationUnit });
    notify('거래처별 장부를 조회했습니다.');
  };

  const reset = () => {
    setDateFrom('');
    setDateTo('');
    setPartnerId('');
    setAccountItemId('');
    setAggregationUnit('일별');
    setFormError('');
    setPage(0);
    setApplied(null);
  };

  const current = data ?? EMPTY_PAGE;
  const rows = current.items;
  let debitSum = 0;
  let creditSum = 0;
  rows.forEach((row) => {
    const amount = Number(row['amount'] ?? 0);
    if (row['dcType'] === 'DEBIT') {
      debitSum += amount;
    } else {
      creditSum += amount;
    }
  });

  const columns: Column[] = [
    { key: 'partnerName', label: '거래처 명칭' },
    { key: 'accountName', label: '계정과목 명칭' },
    { key: 'voucherDate', label: '전표일자', render: (row: Row) => <DateText value={row['voucherDate']} /> },
    { key: 'dcType', label: '차대 구분', render: (row: Row) => <Badge value={row['dcType']} /> },
    { key: 'amount', label: '금액', render: (row: Row) => <Num value={row['amount']} /> },
    { key: 'balance', label: '계정 잔액', render: (row: Row) => <Num value={row['balance']} /> },
    { key: 'periodTotal', label: '일·월별 집계 금액', render: (row: Row) => <Num value={row['periodTotal']} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현재 쪽 요약</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={current.total} />],
            ['차변 합계', <Num value={debitSum} />],
            ['대변 합계', <Num value={creditSum} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>거래처 장부 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={dateFrom} onChange={setDateFrom} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={dateTo} onChange={setDateTo} />
          </Field>
          <Field label="거래처">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
          <Field label="계정과목">
            <LookupSelect table="account_item" role={role} value={accountItemId} onChange={setAccountItemId} placeholder="전체" />
          </Field>
          <Field label="집계 단위">
            <Select
              value={aggregationUnit}
              onChange={setAggregationUnit}
              options={[
                ['일별', '일별'],
                ['월별', '월별'],
              ]}
            />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={current.total} />
        <DataTable
          columns={columns}
          rows={rows}
          empty={applied === null ? '조회 기간을 입력하고 조회해 주세요.' : loading ? '불러오는 중입니다.' : '조회된 내역이 없습니다.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={current.total} onPage={setPage} />
      </section>
    </div>
  );
}
